    sequence_names CONSTANT pg_catalog.text[] := ARRAY['work_history_history_id_seq','delivery_history_history_id_seq','publication_history_history_id_seq']::pg_catalog.text[];
BEGIN
    IF pg_catalog.current_setting('server_version_num')::pg_catalog.int4 < 160000 THEN
        RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unsupported installation profile';
    END IF;
    SELECT oid INTO owner_oid FROM pg_catalog.pg_roles
     WHERE rolname=CURRENT_USER AND NOT rolcanlogin AND NOT rolsuper AND NOT rolbypassrls
       AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication;
    SELECT oid INTO schema_oid FROM pg_catalog.pg_namespace
     WHERE nspname='modkit_events' AND nspowner=owner_oid;
    IF owner_oid IS NULL OR schema_oid IS NULL
       OR NOT pg_catalog.has_database_privilege(owner_oid,pg_catalog.current_database(),'CREATE') THEN
        RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='invalid Events grant owner or schema';
    END IF;
    FOREACH role_name IN ARRAY ARRAY['modkit_runtime','modkit_reconciler','modkit_operator']::pg_catalog.text[] LOOP
        SELECT oid INTO role_oid FROM pg_catalog.pg_roles
         WHERE rolname=role_name AND NOT rolcanlogin AND NOT rolsuper AND NOT rolbypassrls
           AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication;
        IF role_oid IS NULL OR role_oid=owner_oid THEN
            RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='invalid restricted grant role';
        END IF;
    END LOOP;
    -- Inspect all ancestry irrespective of rolinherit, inherit_option or set_option.
    -- A disabled inheritance edge must not hide a later SET ROLE path.
    IF EXISTS (
        WITH RECURSIVE ancestry(origin,ancestor) AS (
            SELECT oid,oid FROM pg_catalog.pg_roles
             WHERE oid=owner_oid OR rolname IN ('modkit_runtime','modkit_reconciler','modkit_operator')
            UNION
            SELECT a.origin,m.roleid FROM ancestry AS a
              JOIN pg_catalog.pg_auth_members AS m ON m.member=a.ancestor
        )
        SELECT 1 FROM ancestry AS a JOIN pg_catalog.pg_roles AS source ON source.oid=a.origin
         JOIN pg_catalog.pg_roles AS target ON target.oid=a.ancestor
        WHERE a.ancestor<>a.origin
          AND NOT (source.rolname IN ('modkit_runtime','modkit_reconciler')
                   AND target.rolname='modkit_operator')
    ) THEN
        RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unsafe grant role ancestry';
    END IF;
    -- Explicit defaults only: absent entries and hard-wired type defaults differ.
    IF EXISTS (
        SELECT 1 FROM pg_catalog.pg_default_acl AS d,
            LATERAL pg_catalog.aclexplode(d.defaclacl) AS a
        WHERE d.defaclrole=owner_oid AND d.defaclnamespace IN (0,schema_oid)
          AND d.defaclobjtype IN ('r','S','f','T','n') AND a.grantee<>owner_oid
    ) THEN
        RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unsafe explicit owner defaults';
    END IF;
    SELECT nspacl INTO object_acl FROM pg_catalog.pg_namespace WHERE oid=schema_oid;
    IF EXISTS (
        WITH actual_acl AS (
            SELECT grantor,grantee,privilege_type,is_grantable
              FROM pg_catalog.aclexplode(COALESCE(object_acl,pg_catalog.acldefault('n',owner_oid)))
        ), wanted AS (
            SELECT grantor,grantee,privilege_type,is_grantable
              FROM pg_catalog.aclexplode(pg_catalog.acldefault('n',owner_oid))
            UNION ALL
            SELECT owner_oid,oid,'USAGE'::pg_catalog.text,FALSE FROM pg_catalog.pg_roles
             WHERE postflight AND rolname IN ('modkit_runtime','modkit_reconciler','modkit_operator')
        )
        (SELECT * FROM actual_acl EXCEPT SELECT * FROM wanted)
        UNION ALL
        (SELECT * FROM wanted EXCEPT SELECT * FROM actual_acl)
    ) THEN
        RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unexpected Events schema ACL';
    END IF;
    FOREACH role_name IN ARRAY ARRAY['modkit_runtime','modkit_reconciler','modkit_operator']::pg_catalog.text[] LOOP
        SELECT oid INTO role_oid FROM pg_catalog.pg_roles WHERE rolname=role_name;
        IF pg_catalog.has_schema_privilege(role_oid,schema_oid,'USAGE') IS DISTINCT FROM postflight
           OR pg_catalog.has_schema_privilege(role_oid,schema_oid,'CREATE') THEN
            RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unsafe effective schema privilege';
        END IF;
    END LOOP;

    IF (SELECT count(*) FROM pg_catalog.pg_proc WHERE pronamespace=schema_oid)
       <>pg_catalog.jsonb_array_length(inventory) THEN
        RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unexpected Events function inventory';
    END IF;
    FOR expected IN SELECT * FROM pg_catalog.jsonb_to_recordset(inventory) AS x(
        signature pg_catalog.text,roles pg_catalog.jsonb,"returns" pg_catalog.text,
        input_types pg_catalog.jsonb,all_types pg_catalog.jsonb,names pg_catalog.jsonb,
        modes pg_catalog.jsonb,definer pg_catalog.bool,volatility pg_catalog.text,
        "setof" pg_catalog.bool,body_sha256 pg_catalog.text)
    LOOP
        object_oid:=pg_catalog.to_regprocedure(expected.signature);
        SELECT * INTO actual FROM pg_catalog.pg_proc WHERE oid=object_oid;
        SELECT ARRAY(SELECT pg_catalog.to_regtype(value)::pg_catalog.oid
                     FROM pg_catalog.jsonb_array_elements_text(expected.input_types)) INTO arg_types;
        SELECT CASE WHEN expected.all_types IS NULL THEN NULL ELSE
            ARRAY(SELECT pg_catalog.to_regtype(value)::pg_catalog.oid
                  FROM pg_catalog.jsonb_array_elements_text(expected.all_types)) END INTO all_types;
        SELECT CASE WHEN expected.names IS NULL THEN NULL ELSE
            ARRAY(SELECT value FROM pg_catalog.jsonb_array_elements_text(expected.names)) END INTO arg_names;
        SELECT CASE WHEN expected.modes IS NULL THEN NULL ELSE
            ARRAY(SELECT value::pg_catalog."char" FROM pg_catalog.jsonb_array_elements_text(expected.modes)) END INTO arg_modes;
        SELECT ARRAY(SELECT value FROM pg_catalog.jsonb_array_elements_text(expected.roles)) INTO allowed_roles;
        IF actual.oid IS NULL OR actual.proowner<>owner_oid OR actual.pronamespace<>schema_oid
           OR actual.prokind<>'f' OR actual.prolang<>(SELECT oid FROM pg_catalog.pg_language WHERE lanname='plpgsql')
           OR actual.prorettype IS DISTINCT FROM pg_catalog.to_regtype(expected."returns")
           OR actual.prosecdef IS DISTINCT FROM expected.definer
           OR actual.provolatile::pg_catalog.text<>expected.volatility
           OR actual.proretset IS DISTINCT FROM expected."setof" OR actual.proisstrict
           OR actual.proleakproof OR actual.proparallel<>'u' OR actual.pronargdefaults<>0
           OR actual.provariadic<>0 OR actual.prosupport<>0
           OR ARRAY(SELECT pg_catalog.unnest(actual.proargtypes)) IS DISTINCT FROM arg_types
           OR actual.proallargtypes IS DISTINCT FROM all_types
           OR actual.proargnames IS DISTINCT FROM arg_names OR actual.proargmodes IS DISTINCT FROM arg_modes
           OR actual.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, pg_temp']::pg_catalog.text[]
           OR pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(actual.prosrc,'UTF8')),'hex')
               IS DISTINCT FROM expected.body_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='Events function identity or ABI mismatch';
        END IF;
        IF EXISTS (
            WITH actual_acl AS (
                SELECT grantor,grantee,privilege_type,is_grantable
                  FROM pg_catalog.aclexplode(COALESCE(actual.proacl,pg_catalog.acldefault('f',owner_oid)))
            ), wanted AS (
                SELECT grantor,grantee,privilege_type,is_grantable
                  FROM pg_catalog.aclexplode(pg_catalog.acldefault('f',owner_oid))
                 WHERE grantee=owner_oid
                UNION ALL
                SELECT owner_oid,oid,'EXECUTE'::pg_catalog.text,FALSE FROM pg_catalog.pg_roles
                 WHERE postflight AND rolname=ANY(allowed_roles)
            )
            (SELECT * FROM actual_acl EXCEPT SELECT * FROM wanted)
            UNION ALL
            (SELECT * FROM wanted EXCEPT SELECT * FROM actual_acl)
        ) THEN
            RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unexpected Events function ACL';
        END IF;
        FOREACH role_name IN ARRAY ARRAY['modkit_runtime','modkit_reconciler','modkit_operator']::pg_catalog.text[] LOOP
            SELECT oid INTO role_oid FROM pg_catalog.pg_roles WHERE rolname=role_name;
            IF pg_catalog.has_function_privilege(role_oid,object_oid,'EXECUTE')
                   IS DISTINCT FROM (postflight AND role_name=ANY(allowed_roles))
               OR pg_catalog.has_function_privilege(role_oid,object_oid,'EXECUTE WITH GRANT OPTION') THEN
                RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unsafe effective Events execution';
            END IF;
        END LOOP;
    END LOOP;
    -- Exact owned tables/sequences/composite, with only indexes on those tables.
    IF EXISTS (
        SELECT 1 FROM pg_catalog.pg_class AS c WHERE c.relnamespace=schema_oid
          AND (c.relowner<>owner_oid OR c.relrowsecurity OR c.relforcerowsecurity
            OR NOT (
                (c.relkind='r' AND c.relname=ANY(relation_names))
                OR (c.relkind='S' AND c.relname=ANY(sequence_names))
                OR (c.relkind='c' AND c.relname='_parse_result')
                OR (c.relkind='i' AND c.relname=ANY(index_names) AND EXISTS (
                    SELECT 1 FROM pg_catalog.pg_index AS i JOIN pg_catalog.pg_class AS parent
                      ON parent.oid=i.indrelid
                    WHERE i.indexrelid=c.oid AND parent.relnamespace=schema_oid
                      AND parent.relname=ANY(relation_names)))))
    ) THEN
        RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unexpected Events relation inventory';
    END IF;
    IF (SELECT count(*) FROM pg_catalog.pg_class WHERE relnamespace=schema_oid AND relkind='i')
       <>pg_catalog.cardinality(index_names) THEN
        RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='missing Events index';
    END IF;
    IF (SELECT count(*) FROM pg_catalog.pg_trigger AS t JOIN pg_catalog.pg_class AS c
         ON c.oid=t.tgrelid WHERE c.relnamespace=schema_oid AND NOT t.tgisinternal)
         <>pg_catalog.jsonb_array_length(triggers) THEN
        RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unexpected Events trigger inventory';
    END IF;
    FOR expected IN SELECT * FROM pg_catalog.jsonb_to_recordset(triggers)
        AS x(name pg_catalog.text,table_name pg_catalog.text,"function" pg_catalog.text) LOOP
        IF NOT EXISTS (
            SELECT 1 FROM pg_catalog.pg_trigger AS t
            WHERE t.tgrelid=pg_catalog.to_regclass('modkit_events.'||expected.table_name)
              AND t.tgname=expected.name AND NOT t.tgisinternal AND t.tgenabled='O'
              AND t.tgfoid=pg_catalog.to_regprocedure(expected."function") AND t.tgnargs=0
        ) THEN
            RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unexpected Events trigger target';
        END IF;
    END LOOP;
    FOR expected IN SELECT * FROM pg_catalog.jsonb_to_recordset(relations)
        AS x(name pg_catalog.text,"columns" pg_catalog.jsonb)
    LOOP
        object_oid:=pg_catalog.to_regclass('modkit_events.'||expected.name);
        SELECT * INTO actual FROM pg_catalog.pg_class WHERE oid=object_oid;
        IF actual.oid IS NULL OR actual.relkind<>'r' OR actual.relowner<>owner_oid THEN
            RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='missing owned Events table';
        END IF;
        IF EXISTS (
            WITH a AS (SELECT * FROM pg_catalog.aclexplode(COALESCE(actual.relacl,pg_catalog.acldefault('r',owner_oid)))),
                 b AS (SELECT * FROM pg_catalog.aclexplode(pg_catalog.acldefault('r',owner_oid)))
            (SELECT * FROM a EXCEPT SELECT * FROM b) UNION ALL (SELECT * FROM b EXCEPT SELECT * FROM a)
        ) OR EXISTS (
            SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid=object_oid
              AND (attisdropped OR (attacl IS NOT NULL AND pg_catalog.cardinality(attacl)>0))
        ) THEN
            RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unsafe Events table or column ACL';
        END IF;
        IF (SELECT count(*) FROM pg_catalog.pg_attribute WHERE attrelid=object_oid AND attnum>0)
            <>pg_catalog.jsonb_array_length(expected."columns") THEN
            RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unexpected Events columns';
        END IF;
        FOR col IN SELECT x.* FROM pg_catalog.jsonb_array_elements(expected."columns") WITH ORDINALITY AS x(value,n) LOOP
            IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_attribute AS a
                WHERE a.attrelid=object_oid AND a.attnum=col.n
                  AND a.attname=col.value->>'name' AND a.atttypid=pg_catalog.to_regtype(col.value->>'type')
                  AND a.attnotnull=(col.value->>'notnull')::pg_catalog.bool) THEN
                RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='Events column identity mismatch';
            END IF;
        END LOOP;
        FOREACH role_name IN ARRAY ARRAY['modkit_runtime','modkit_reconciler','modkit_operator']::pg_catalog.text[] LOOP
            SELECT oid INTO role_oid FROM pg_catalog.pg_roles WHERE rolname=role_name;
            IF pg_catalog.has_table_privilege(role_oid,object_oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
               OR EXISTS (SELECT 1 FROM pg_catalog.pg_attribute AS a WHERE a.attrelid=object_oid AND a.attnum>0
                    AND pg_catalog.has_column_privilege(role_oid,object_oid,a.attnum,'SELECT,INSERT,UPDATE,REFERENCES')) THEN
                RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='restricted Events table or column access';
            END IF;
        END LOOP;
    END LOOP;
    FOREACH role_name IN ARRAY sequence_names LOOP
        object_oid:=pg_catalog.to_regclass('modkit_events.'||role_name);
        SELECT * INTO actual FROM pg_catalog.pg_class WHERE oid=object_oid;
        IF actual.oid IS NULL OR actual.relkind<>'S' OR actual.relowner<>owner_oid OR EXISTS (
            WITH a AS (SELECT * FROM pg_catalog.aclexplode(COALESCE(actual.relacl,pg_catalog.acldefault('s',owner_oid)))),
                 b AS (SELECT * FROM pg_catalog.aclexplode(pg_catalog.acldefault('s',owner_oid)))
            (SELECT * FROM a EXCEPT SELECT * FROM b) UNION ALL (SELECT * FROM b EXCEPT SELECT * FROM a)
        ) THEN
            RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unsafe Events sequence ACL';
        END IF;
        FOR role_oid IN SELECT oid FROM pg_catalog.pg_roles
            WHERE rolname IN ('modkit_runtime','modkit_reconciler','modkit_operator') LOOP
            IF pg_catalog.has_sequence_privilege(role_oid,object_oid,'SELECT,USAGE,UPDATE') THEN
                RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='restricted Events sequence access';
            END IF;
        END LOOP;
    END LOOP;
    -- Canonical implicit row/array defaults are NOT private-table privileges.
    IF (SELECT count(*) FROM pg_catalog.pg_type WHERE typnamespace=schema_oid)
       <>2*(pg_catalog.cardinality(relation_names)+1) THEN
        RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unexpected Events type inventory';
    END IF;
    FOR role_name IN SELECT pg_catalog.unnest(relation_names||ARRAY['_parse_result']::pg_catalog.text[]) LOOP
        object_oid:=pg_catalog.to_regtype('modkit_events.'||role_name);
        SELECT t.*,c.relkind,c.reltype INTO typ FROM pg_catalog.pg_type AS t
            JOIN pg_catalog.pg_class AS c ON c.oid=t.typrelid WHERE t.oid=object_oid;
        IF typ.oid IS NULL OR typ.typowner<>owner_oid OR typ.typnamespace<>schema_oid
           OR typ.typtype<>'c' OR typ.reltype<>typ.oid
           OR typ.relkind<>CASE WHEN role_name='_parse_result' THEN 'c' ELSE 'r' END
           OR NOT EXISTS (
                SELECT 1 FROM pg_catalog.pg_type AS a WHERE a.oid=typ.typarray
                  AND a.typelem=typ.oid AND a.typowner=owner_oid AND a.typnamespace=schema_oid
                  AND a.typcategory='A' AND a.typtype='b' AND a.typsubscript='pg_catalog.array_subscript_handler'::pg_catalog.regproc
                  AND a.typacl IS NULL)
        THEN
            RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='Events type topology mismatch';
        END IF;
        IF role_name='_parse_result' THEN
            -- Explicit private composite excludes built-in PUBLIC USAGE.
            IF EXISTS (SELECT 1 FROM pg_catalog.aclexplode(COALESCE(typ.typacl,pg_catalog.acldefault('T',owner_oid))) AS a
                WHERE a.grantee<>owner_oid OR a.grantor<>owner_oid OR a.privilege_type<>'USAGE' OR a.is_grantable)
               OR NOT EXISTS (SELECT 1 FROM pg_catalog.aclexplode(typ.typacl) AS a
                    WHERE a.grantee=owner_oid AND a.grantor=owner_oid AND a.privilege_type='USAGE' AND NOT a.is_grantable)
               OR (SELECT ARRAY(SELECT attname::pg_catalog.text||':'||atttypid::pg_catalog.regtype::pg_catalog.text
                     FROM pg_catalog.pg_attribute WHERE attrelid=typ.typrelid AND attnum>0 ORDER BY attnum))
                     IS DISTINCT FROM ARRAY['value:bytea','after_pos:integer','nodes:integer']::pg_catalog.text[] THEN
                RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unsafe private Events type';
            END IF;
        ELSIF typ.typacl IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unexpected explicit row type ACL';
        END IF;
        FOR role_oid IN SELECT oid FROM pg_catalog.pg_roles
            WHERE rolname IN ('modkit_runtime','modkit_reconciler','modkit_operator') LOOP
            IF pg_catalog.has_type_privilege(role_oid,typ.oid,'USAGE') IS DISTINCT FROM (role_name<>'_parse_result')
               OR pg_catalog.has_type_privilege(role_oid,typ.typarray,'USAGE') IS DISTINCT FROM (role_name<>'_parse_result')
               OR pg_catalog.has_type_privilege(role_oid,typ.oid,'USAGE WITH GRANT OPTION')
               OR pg_catalog.has_type_privilege(role_oid,typ.typarray,'USAGE WITH GRANT OPTION') THEN
                RAISE EXCEPTION USING ERRCODE='PZ011',MESSAGE='unsafe effective Events type privilege';
            END IF;
        END LOOP;
    END LOOP;
END
$events_preflight$;

