    index_names CONSTANT pg_catalog.text[] := ARRAY['work_key_identity','work_discovery_scan','work_ready_scan','work_recovery_scan','work_history_page','delivery_history_page','outbox_scan','publication_history_page','work_history_complete_lookup','work_namespace_created_page','work_jobs_created_page','schema_versions_pkey','subscriptions_pkey','work_pkey','finalization_guards_pkey','finalization_guards_work_id_root_xid_key','inbox_pkey','inbox_subscription_id_event_digest_key','attempts_pkey','attempts_dispatch_id_key','work_history_pkey','delivery_history_pkey','outbox_pkey','outbox_intent_id_key','publication_history_pkey','mutation_operations_pkey','job_payloads_pkey']::pg_catalog.text[];
